export async function createScene(engine, canvas, BABYLON) {
  console.clear();
  const scene = new BABYLON.Scene(engine);
  scene.useRightHandedSystem = true;

  const camera = new BABYLON.ArcRotateCamera("camera", BABYLON.Tools.ToRadians(90), BABYLON.Tools.ToRadians(65), 10, BABYLON.Vector3.Zero(), scene);
  camera.setTarget(new BABYLON.Vector3(-3.37, -5.55, 3.39));
  camera.alpha = 2.16;
  camera.beta = 0.959;
  camera.radius = 43.3;
  camera.inertia = 0.4;
  camera.wheelDeltaPercentage = 0.3;
  camera.panningSensibility = 10000;
  camera.minZ = 0.01;
  camera.maxZ = 10000;
  camera.zoomToMouseLocation = true;
  camera.attachControl(canvas, true);

  const light = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);
  light.intensity = 0.8;

  const ground = BABYLON.MeshBuilder.CreateGround("ground", { width: 50, height: 50 }, scene);
  ground.visibility = 0.4;
  var gridMat = new BABYLON.GridMaterial("grid mat", scene);
  gridMat.majorUnitFrequency = 6;
  gridMat.minorUnitVisibility = 0.43;
  gridMat.gridRatio = 1;
  gridMat.mainColor = new BABYLON.Color3(0.79, 0.79, 0.79);
  gridMat.lineColor = new BABYLON.Color3(0, 0, 0);
  gridMat.backFaceCulling = false;
  ground.material = gridMat;

  const glbCache = {};

  const proxyMaterial = new BABYLON.StandardMaterial("proxyMat", scene);
  proxyMaterial.alpha = 0.4;
  proxyMaterial.diffuseColor = new BABYLON.Color3(0, 1, 0);
  proxyMaterial.emissiveColor = new BABYLON.Color3(0, 1, 0);

  const sizeMap = {
    metal_slug_tank: {
      size: new BABYLON.Vector3(0.074, 0.074, 0.084),
      file: "metal_slug_tank.glb",
      scaleHint: 100,
    },
    pizza: {
      size: new BABYLON.Vector3(0.369, 0.063, 0.369),
      file: "pizza.glb",
      scaleHint: 10,
    },
    ship_repair_dock: {
      size: new BABYLON.Vector3(7.901, 5.026, 10.1),
      file: "ship_repair_dock_-_starcraft_2.glb",
      scaleHint: 1,
    },
  };

  let currentKey = "metal_slug_tank";
  let currentSize = sizeMap[currentKey].size;
  let currentGLB = sizeMap[currentKey].file;
  let currentScale = sizeMap[currentKey].scaleHint;

  let previewBox = null;

  const updatePreview = (key) => {
    currentKey = key;
    currentSize = sizeMap[key].size;
    currentGLB = sizeMap[key].file;
    currentScale = sizeMap[key].scaleHint;

    if (previewBox) previewBox.dispose();

    previewBox = BABYLON.MeshBuilder.CreateBox(
      "proxy",
      {
        width: currentSize.x * currentScale,
        height: currentSize.y * currentScale,
        depth: currentSize.z * currentScale,
      },
      scene
    );
    previewBox.material = proxyMaterial;
    previewBox.isPickable = false;
    previewBox.position.y = (currentSize.y * currentScale) / 2;
  };

  scene.onPointerObservable.add((pointerInfo) => {
    if (pointerInfo.type === BABYLON.PointerEventTypes.POINTERMOVE) {
      const pick = scene.pick(scene.pointerX, scene.pointerY, (mesh) => mesh === ground);
      if (pick.hit && previewBox) {
        previewBox.position.x = pick.pickedPoint.x;
        previewBox.position.z = pick.pickedPoint.z;
      }
    }

    if (pointerInfo.type === BABYLON.PointerEventTypes.POINTERDOWN) {
      if (pointerInfo.event.button === 0 && previewBox) {
        const x = previewBox.position.x;
        const z = previewBox.position.z;

        if (glbCache[currentKey]) {
          const { root, minY, scaleHint } = glbCache[currentKey];
          const clone = root.clone("clone_" + currentKey);
          clone.setEnabled(true);
          clone.getChildMeshes(true).forEach((m) => m.setEnabled(true));
          clone.getChildTransformNodes(true).forEach((n) => n.setEnabled(true));
          clone.scaling.set(scaleHint, scaleHint, scaleHint);
          clone.position.set(x, -minY * scaleHint, z);
        } else {
          BABYLON.SceneLoader.ImportMeshAsync("", "https://raw.githubusercontent.com/UN1TOne/3DAsset/master/", currentGLB, scene).then((result) => {
            const root = result.meshes[0];
            const children = root.getChildMeshes();

            let min = null,
              max = null;
            for (let i = 0; i < children.length; i++) {
              children[i].computeWorldMatrix(true);
              const boundingInfo = children[i].getBoundingInfo();
              const meshMin = boundingInfo.boundingBox.minimumWorld;
              const meshMax = boundingInfo.boundingBox.maximumWorld;
              if (!min) {
                min = meshMin.clone();
                max = meshMax.clone();
              } else {
                min = BABYLON.Vector3.Minimize(min, meshMin);
                max = BABYLON.Vector3.Maximize(max, meshMax);
              }
            }

            const size = max.subtract(min);
            const code = `const size = new BABYLON.Vector3(${size.x.toFixed(3)}, ${size.y.toFixed(3)}, ${size.z.toFixed(3)});`;
            navigator.clipboard.writeText(code).then(() => console.log("[Copied to clipboard] " + code));

            root.setEnabled(false);
            glbCache[currentKey] = {
              root: root,
              minY: min.y,
              scaleHint: currentScale,
            };

            const clone = root.clone("clone_" + currentKey);
            clone.setEnabled(true);
            clone.getChildMeshes(true).forEach((m) => m.setEnabled(true));
            clone.getChildTransformNodes(true).forEach((n) => n.setEnabled(true));
            clone.scaling.set(currentScale, currentScale, currentScale);
            clone.position.set(x, -min.y * currentScale, z);
          });
        }
      }
    }
  });

  const advancedTexture = BABYLON.GUI.AdvancedDynamicTexture.CreateFullscreenUI("UI");

  const panel = new BABYLON.GUI.StackPanel();
  panel.width = "220px";
  panel.isVertical = true;
  panel.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
  panel.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_TOP;
  panel.paddingTop = "10px";
  panel.paddingLeft = "10px";
  advancedTexture.addControl(panel);

  const makeButton = (text, key) => {
    const button = BABYLON.GUI.Button.CreateSimpleButton("btn_" + key, text);
    button.width = "200px";
    button.height = "40px";
    button.color = "white";
    button.background = "#2c3e50";
    button.cornerRadius = 10;
    button.thickness = 1;
    button.paddingBottom = "10px";
    button.onPointerUpObservable.add(() => updatePreview(key));
    return button;
  };

  panel.addControl(makeButton("Metal Slug Tank", "metal_slug_tank"));
  panel.addControl(makeButton("Pizza", "pizza"));
  panel.addControl(makeButton("Ship Repair Dock", "ship_repair_dock"));

  updatePreview(currentKey);

  return scene;
}
